#!/usr/bin/env python3
import sys, os, re, gzip, bz2, lzma, json, csv, io, sqlite3, subprocess, datetime, time, stat
from dataclasses import dataclass, field
from typing import List, Optional, Any, Tuple

VERSION = "lnav 0.14.0-07efb63"
HELP_VERSION = "lnav 0.14.0-07efb63"
MONTHS = {m:i+1 for i,m in enumerate(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])}

@dataclass
class Record:
    raw_lines: List[str]
    log_time: Optional[datetime.datetime] = None
    log_level: Optional[str] = None
    log_hostname: Optional[str] = None
    log_pid: Optional[str] = None
    log_procname: Optional[str] = None
    log_syslog_tag: Optional[str] = None
    log_body: str = ""
    recognized: bool = False
    source: str = ""
    line_no: int = 0
    marked: bool = False
    extra: dict = field(default_factory=dict)

    @property
    def text(self):
        return "\n".join(self.raw_lines)

    @property
    def display(self):
        # JSON records are displayed in a concise, lnav-like form.
        if self.extra.get('json_display'):
            return self.extra['json_display']
        return self.text


def eprint(s=""):
    sys.stderr.write(str(s) + "\n")


def squote(s):
    return "“" + s + "”"


def fmt_dt(dt: Optional[datetime.datetime]):
    if dt is None:
        return None
    return dt.strftime("%Y-%m-%d %H:%M:%S.%f")


def parse_time_arg(s: str) -> Optional[datetime.datetime]:
    now = datetime.datetime.now(datetime.timezone.utc).astimezone().replace(tzinfo=None)
    txt = s.strip()
    # Try common absolute forms.
    for fmt in ["%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d"]:
        try:
            return datetime.datetime.strptime(txt.rstrip('Z'), fmt)
        except ValueError:
            pass
    # Time-only: original interprets it as today.
    for fmt in ["%H:%M:%S.%f", "%H:%M:%S", "%H:%M"]:
        try:
            t = datetime.datetime.strptime(txt, fmt).time()
            return datetime.datetime(now.year, now.month, now.day, t.hour, t.minute, t.second, t.microsecond)
        except ValueError:
            pass
    return None


def level_from_body(body: str) -> str:
    b = body.lower()
    if re.search(r'\b(fatal|critical|crit|panic|exception|error|err|failed|failure)\b', b):
        return 'error'
    if re.search(r'\b(warn|warning)\b', b):
        return 'warning'
    if re.search(r'\b(debug|trace)\b', b):
        return 'debug'
    return 'info'


def parse_iso_datetime(s: str) -> Optional[datetime.datetime]:
    z = s.strip()
    # Normalize timezone; lnav table output uses UTC-less timestamp.
    try_s = z
    if try_s.endswith('Z'):
        try_s = try_s[:-1] + '+00:00'
    try:
        dt = datetime.datetime.fromisoformat(try_s)
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        return dt
    except Exception:
        pass
    for fmt in ["%Y-%m-%d %H:%M:%S,%f", "%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S"]:
        try:
            return datetime.datetime.strptime(z, fmt)
        except Exception:
            pass
    return None


def parse_line(line: str, source: str, no: int) -> Optional[Record]:
    # syslog: Jan  1 00:00:01 host app[123]: msg
    m = re.match(r'^(?P<mon>[A-Z][a-z]{2})\s+(?P<day>\d{1,2})\s+(?P<h>\d\d):(?P<mi>\d\d):(?P<s>\d\d)\s+(?P<host>\S+)\s+(?P<tag>[^:]+):\s?(?P<body>.*)$', line)
    if m and m.group('mon') in MONTHS:
        yr = datetime.datetime.now().year
        dt = datetime.datetime(yr, MONTHS[m.group('mon')], int(m.group('day')), int(m.group('h')), int(m.group('mi')), int(m.group('s')))
        tag = m.group('tag')
        proc = tag
        pid = None
        pm = re.match(r'(.+?)\[(.*?)\]$', tag)
        if pm:
            proc, pid = pm.group(1), pm.group(2)
        body = m.group('body')
        return Record([line], dt, level_from_body(body), m.group('host'), pid, proc, tag, body, True, source, no)

    # RFC5424-ish / generic ISO timestamp at start.
    m = re.match(r'^(?P<ts>\d{4}-\d\d-\d\d[T ]\d\d:\d\d:\d\d(?:[\.,]\d+)?(?:Z|[+-]\d\d:?\d\d)?)\s*(?P<rest>.*)$', line)
    if m:
        dt = parse_iso_datetime(m.group('ts').replace(',', '.'))
        rest = m.group('rest')
        level = None
        lm = re.search(r'\b(TRACE|DEBUG|INFO|NOTICE|WARN|WARNING|ERROR|ERR|FATAL|CRITICAL)\b', rest, re.I)
        if lm:
            l = lm.group(1).lower()
            level = 'warning' if l == 'warn' else ('error' if l in ('err','fatal','critical') else l)
        else:
            level = level_from_body(rest)
        return Record([line], dt, level, None, None, None, None, rest, True, source, no)

    # Apache combined/common access log.
    m = re.match(r'^(?P<ip>\S+)\s+\S+\s+\S+\s+\[(?P<ts>\d{1,2}/[A-Za-z]{3}/\d{4}:\d\d:\d\d:\d\d\s+[+-]\d{4})\]\s+"(?P<req>[^"]*)"\s+(?P<status>\d{3})\s+(?P<size>\S+)(?P<rest>.*)$', line)
    if m:
        try:
            dt = datetime.datetime.strptime(m.group('ts'), "%d/%b/%Y:%H:%M:%S %z").astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            dt = None
        status = int(m.group('status'))
        level = 'error' if status >= 500 else ('warning' if status >= 400 else 'info')
        body = f"{m.group('ip')} {m.group('req')} {m.group('status')} {m.group('size')}".strip()
        rec = Record([line], dt, level, None, None, None, None, body, True, source, no)
        rec.extra['col_0'] = m.group('ip')
        rec.extra['status'] = status
        rec.extra['request'] = m.group('req')
        return rec

    # JSON-lines: recognize objects with a usable timestamp and message/body.
    if line.lstrip().startswith('{'):
        try:
            obj = json.loads(line)
            if isinstance(obj, dict):
                ts = None
                for k in ['time','timestamp','@timestamp','ts','date']:
                    if k in obj:
                        ts = parse_iso_datetime(str(obj[k]))
                        break
                msg = None
                for k in ['msg','message','MESSAGE','body','event']:
                    if k in obj:
                        msg = str(obj[k])
                        break
                lvl = None
                for k in ['level','severity','log.level','PRIORITY']:
                    if k in obj:
                        lvl = str(obj[k]).lower()
                        break
                if ts is not None and msg is not None:
                    if lvl is None or lvl.isdigit():
                        lvl = level_from_body(msg)
                    if lvl == 'warn': lvl = 'warning'
                    if lvl in ('err','fatal','critical'): lvl = 'error'
                    rec = Record([line], ts, lvl, None, None, None, None, msg, True, source, no)
                    rest = []
                    for k,v in obj.items():
                        if k in ('time','timestamp','@timestamp','ts','date','msg','message','MESSAGE','body','event','level','severity','log.level','PRIORITY'):
                            continue
                        rest.append(f"  {k}: {v}")
                    disp = f"{obj.get('time', obj.get('timestamp', obj.get('@timestamp', fmt_dt(ts))))} -[-] {lvl.upper():<8} {msg}"
                    if rest:
                        disp += "\n" + "\n".join(rest)
                    rec.extra['json_display'] = disp
                    rec.extra['json'] = obj
                    return rec
        except Exception:
            pass
    return None


def finalize_records(lines: List[str], source: str, timestamps_for_stdin=False) -> Tuple[List[Record], List[str]]:
    records: List[Record] = []
    text_lines: List[str] = []
    cur: Optional[Record] = None
    for idx, raw in enumerate(lines):
        line = raw.rstrip('\n')
        if timestamps_for_stdin:
            # Match lnav's ISO-ish UTC offset style for stdin -t.
            now = datetime.datetime.now(datetime.timezone.utc).astimezone()
            off = now.strftime('%z')
            line = now.strftime('%Y-%m-%dT%H:%M:%S.%f') + off + ' ' + line
        rec = parse_line(line, source, idx)
        if rec is not None:
            if cur is not None:
                records.append(cur)
            cur = rec
        else:
            text_lines.append(line)
            if cur is not None and line != "":
                cur.raw_lines.append(line)
                cur.log_body = (cur.log_body + "\n" + line) if cur.log_body else line
            else:
                # Plain text line: visible in the text/log output, but not a SQL log row.
                records.append(Record([line], None, None, None, None, None, None, line, False, source, idx))
                cur = None
    if cur is not None:
        records.append(cur)
    return records, text_lines


def open_text_file(path: str) -> List[str]:
    if path.endswith('.gz'):
        with gzip.open(path, 'rt', errors='replace') as f: return f.readlines()
    if path.endswith('.bz2'):
        with bz2.open(path, 'rt', errors='replace') as f: return f.readlines()
    if path.endswith('.xz') or path.endswith('.lzma'):
        with lzma.open(path, 'rt', errors='replace') as f: return f.readlines()
    with open(path, 'r', errors='replace') as f:
        return f.readlines()


def collect_paths(paths: List[str], recursive=False) -> List[str]:
    out = []
    for p in paths:
        if os.path.isdir(p):
            if recursive:
                for root, dirs, files in os.walk(p):
                    for name in sorted(files):
                        out.append(os.path.join(root, name))
            else:
                for name in sorted(os.listdir(p)):
                    fp = os.path.join(p, name)
                    if os.path.isfile(fp): out.append(fp)
        else:
            out.append(p)
    return out


def recognized_file(records: List[Record]) -> bool:
    return any(r.recognized for r in records)


def merge_records_by_file(file_recs: List[List[Record]]) -> List[Record]:
    # lnav merges per-file streams by the timestamp at each stream head and preserves file order within a stream.
    heads = [0]*len(file_recs)
    result = []
    while True:
        candidates = []
        for i, recs in enumerate(file_recs):
            if heads[i] < len(recs):
                rec = recs[heads[i]]
                key = rec.log_time if rec.log_time is not None else datetime.datetime.max
                candidates.append((key, i, rec))
        if not candidates: break
        key,i,rec = min(candidates, key=lambda x: (x[0], x[1]))
        result.append(rec); heads[i]+=1
    return result


class Options:
    def __init__(self):
        self.help=False; self.version=False; self.internal_help=False
        self.headless=False; self.no_default=False; self.quiet=False
        self.recursive=False; self.rotated=False; self.warn=False; self.check=False
        self.update=False; self.management=False; self.install=False
        self.install_args=[]; self.config_dirs=[]; self.debug_file=None
        self.commands=[]; self.exec_cmds=[]; self.paths=[]; self.stdin_timestamps=False
        self.since=None; self.until=None; self.invalid=None; self.invalid_code=109
        self.endopts=False


def missing_arg(opt, what):
    return (114, f"  error: invalid command-line arguments\n reason: {opt}: 1 required {what} missing\n")


def parse_args(argv: List[str]) -> Options:
    o = Options(); i=0
    takes = {'I':'TEXT:DIR','d':'FILE','c':'','f':'','e':'','S':'TEXT','U':'TEXT'}
    while i < len(argv):
        a = argv[i]
        if o.endopts:
            o.paths.append(a); i+=1; continue
        if a == '--':
            o.endopts=True; i+=1; continue
        if a in ('--help',): o.help=True; i+=1; continue
        if a in ('--version',): o.version=True; i+=1; continue
        if a in ('--since','--until'):
            if i+1 >= len(argv):
                code,msg = missing_arg(a, 'TEXT'); o.invalid=(code,msg); return o
            val=argv[i+1]; dt=parse_time_arg(val)
            if dt is None:
                o.invalid=(1, f"  error: invalid '{'since' if a=='--since' else 'until'}' time {squote(val)}\n reason: Unrecognized input\n")
                return o
            if a=='--since': o.since=dt
            else: o.until=dt
            i+=2; continue
        if a.startswith('--'):
            # Help/version have precedence; otherwise unknown.
            o.invalid=(109, f"  error: invalid command-line arguments\n reason: The following argument was not expected: {a}\n")
            i+=1; continue
        if a.startswith('-') and a != '-':
            j=1
            while j < len(a):
                ch=a[j]
                if ch == 'h': o.help=True; j+=1; continue
                if ch == 'V': o.version=True; j+=1; continue
                if ch == 'H': o.internal_help=True; j+=1; continue
                if ch == 'n': o.headless=True; j+=1; continue
                if ch == 'N': o.no_default=True; j+=1; continue
                if ch == 'q': o.quiet=True; j+=1; continue
                if ch == 'r': o.recursive=True; j+=1; continue
                if ch == 'R': o.rotated=True; j+=1; continue
                if ch == 'W': o.warn=True; j+=1; continue
                if ch == 'C': o.check=True; j+=1; continue
                if ch == 'u': o.update=True; j+=1; continue
                if ch == 'm': o.management=True; j+=1; continue
                if ch == 'i': o.install=True; j+=1; continue
                if ch == 't': o.stdin_timestamps=True; j+=1; continue
                if ch in takes:
                    # Rest of cluster or next argv is the argument.
                    if j+1 < len(a): val=a[j+1:]; j=len(a)
                    else:
                        if i+1 >= len(argv):
                            code,msg=missing_arg('-'+ch, takes[ch]); o.invalid=(code,msg); return o
                        val=argv[i+1]; i+=1; j=len(a)
                    if ch=='I': o.config_dirs.append(val)
                    elif ch=='d': o.debug_file=val
                    elif ch=='c': o.commands.append(val)
                    elif ch=='f': o.commands.append('|' + val)
                    elif ch=='e': o.exec_cmds.append(val)
                    elif ch=='S':
                        dt=parse_time_arg(val)
                        if dt is None:
                            o.invalid=(1, f"  error: invalid 'since' time {squote(val)}\n reason: Unrecognized input\n"); return o
                        o.since=dt
                    elif ch=='U':
                        dt=parse_time_arg(val)
                        if dt is None:
                            o.invalid=(1, f"  error: invalid 'until' time {squote(val)}\n reason: Unrecognized input\n"); return o
                    continue
                # Unknown short; keep parsing to allow later -h/-V to override.
                if o.invalid is None:
                    o.invalid=(109, f"  error: invalid command-line arguments\n reason: The following argument was not expected: -{ch}\n")
                j+=1
            i+=1; continue
        o.paths.append(a); i+=1
    # Validate command prefixes early.
    for c in o.commands:
        if c == '|' or c.startswith('|'):
            continue
        if not (c.startswith(':') or c.startswith(';')):
            o.invalid=(105, "  error: invalid value for “-c” option\n --> command-line argument\n |  -c %-36s\n |     ^ command type prefix is missing    \n = help: command arguments must start with one of the following symbols to denote the type of command:\n            : - an lnav command   (e.g. :goto 42)\n            ; - an SQL statement  (e.g. ;SELECT * FROM syslog_log)\n            | - an lnav script    (e.g. |rename-stdin foo)\n" % c)
            return o
    if o.headless and o.management:
        o.invalid=(109, "  error: invalid command-line arguments\n reason: The following argument was not expected: -m\n")
    if o.headless and o.install:
        o.invalid=(108, "  error: invalid command-line arguments\n reason: -i excludes -n\n")
    return o


