def internal_help_text():
    # Condensed but faithful beginning of lnav's internal help.
    return """
lnav 0.14.0

A fancy log file viewer for the terminal.

Overview

The Logfile Navigator, lnav, is an enhanced log file viewer that takes
advantage of any semantic information that can be gleaned from the
files being viewed, such as timestamps and log levels. Using this
extra semantic information, lnav can do things like interleaving
messages from different files, generate histograms of messages over
time, and providing hotkeys for navigating through the file.

Opening Paths/URLs

The main arguments to lnav are the local/remote files, directories,
glob patterns, or URLs to be viewed. If no arguments are given, the
default syslog file for your system will be opened. These arguments
will be polled periodically so that any new data or files will be
automatically loaded.

Options

Lnav takes a list of files to view and/or you can use the flag
arguments to load well-known log files, such as the syslog log files.
The flag arguments are:

 •  -r  Recursively load files from the given directory hierarchies.
 •  -R  Load older rotated log files as well.

If you do not want the default syslog file to be loaded when no files
are specified, you can pass the  -N  flag.

Any files given on the command-line are scanned to determine their log
file format and to create an index for each line in the file. You do
not have to manually specify the log file format. The currently
supported formats are: syslog, apache, strace, tcsh history, and
generic log files with timestamps.

Lnav will also display data piped in on the standard input.

To automatically execute queries or lnav commands after the files have
been loaded, you can use the following options:

 •  -c cmd  A command, query, or file to execute. A colon (:) is used
   for built-in commands; a semi-colon (;) for SQL queries; and a pipe
   symbol (|) for executing a file containing other commands.
 •  -f file  A file that contains commands, queries, or files to
   execute. This option is a shortcut for -c '|file'.

To execute commands/queries without opening the interactive text UI,
you can pass the -n option.

Display

The main part of the display shows the log lines from the files
interleaved based on time-of-day. New lines are automatically loaded
as they are appended to the files.

Key Bindings

  ?    View/leave the online help text.
  q    Quit the program.
  /    Search using regular expressions.
  e/E  Jump to next/previous error.
"""


def visible_records(records: List[Record], filters: List[Tuple[str,re.Pattern]], since, until, offset=0) -> List[Record]:
    out=[]
    for r in records:
        if r.recognized and since and r.log_time and r.log_time < since: continue
        if r.recognized and until and r.log_time and r.log_time > until: continue
        ok=True
        for typ,pat in filters:
            m = pat.search(r.text) or pat.search(r.log_body or '')
            if typ=='in' and not m: ok=False
            if typ=='out' and m: ok=False
        if ok: out.append(r)
    return out[offset:]


def setup_db(records: List[Record]) -> sqlite3.Connection:
    con = sqlite3.connect(':memory:')
    con.row_factory = sqlite3.Row
    # REGEXP helper.
    con.create_function('regexp', 2, lambda p,x: 1 if x is not None and re.search(p, str(x)) else 0)
    cols = ', '.join([f'col_{i} TEXT' for i in range(10)])
    base_cols = f"log_line INTEGER PRIMARY KEY, log_time DATETIME, log_level TEXT, log_body TEXT, log_hostname TEXT, log_msgid TEXT, log_pid TEXT, log_pri INTEGER, log_procname TEXT, log_struct TEXT, log_syslog_tag TEXT, syslog_version INTEGER, log_msg_format TEXT, log_msg_values TEXT, log_msg_src TEXT, log_stack_trace TEXT, log_part TEXT, log_idle_msecs INTEGER, log_mark BOOLEAN, log_comment TEXT, log_tags TEXT, log_annotations TEXT, log_filters TEXT, {cols}"
    con.execute(f'CREATE TABLE all_logs ({base_cols})')
    con.execute(f'CREATE TABLE logline ({base_cols})')
    for idx,r in enumerate([x for x in records if x.recognized]):
        vals = {
            'log_line': idx, 'log_time': fmt_dt(r.log_time), 'log_level': r.log_level, 'log_body': r.log_body,
            'log_hostname': r.log_hostname, 'log_msgid': None, 'log_pid': r.log_pid, 'log_pri': None,
            'log_procname': r.log_procname, 'log_struct': None, 'log_syslog_tag': r.log_syslog_tag,
            'syslog_version': None, 'log_msg_format': r.log_body, 'log_msg_values': 'null' if r.extra.get('json') else None,
            'log_msg_src': None, 'log_stack_trace': None, 'log_part': None, 'log_idle_msecs': 0,
            'log_mark': 1 if r.marked else 0, 'log_comment': None, 'log_tags': None,
            'log_annotations': None, 'log_filters': None,
        }
        ips = re.findall(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', r.log_body + ' ' + r.text)
        for i in range(10): vals[f'col_{i}'] = r.extra.get(f'col_{i}') or (ips[i] if i < len(ips) else None)
        names = list(vals.keys())
        con.execute('INSERT INTO all_logs (%s) VALUES (%s)' % (','.join(names), ','.join(['?']*len(names))), [vals[n] for n in names])
        # lnav's logline commonly corresponds to rows in the log view; expose the first row for broad compatibility.
        if idx == 0:
            con.execute('INSERT INTO logline (%s) VALUES (%s)' % (','.join(names), ','.join(['?']*len(names))), [vals[n] for n in names])
    con.commit(); return con


def value_display(v):
    if v is None: return '<NULL>'
    if isinstance(v, bytes): return v.decode(errors='replace')
    return str(v)


def format_table(headers: List[str], rows: List[Tuple[Any,...]]) -> str:
    if not headers:
        return ''
    # Determine numeric columns from values.
    numeric=[]
    for ci,h in enumerate(headers):
        isnum=True; anynon=False
        for row in rows:
            v=row[ci]
            if v is None: continue
            anynon=True
            if not isinstance(v, (int,float)):
                isnum=False; break
        numeric.append(isnum and anynon)
    widths=[]
    for ci,h in enumerate(headers):
        mx=len(str(h))
        for row in rows:
            mx=max(mx, len(value_display(row[ci])))
        if numeric[ci]: mx=max(mx,10)
        widths.append(mx)
    lines=[]
    lines.append(''.join(str(h).center(widths[i]) + ' ' for i,h in enumerate(headers)))
    for row in rows:
        s=''
        for i,v in enumerate(row):
            txt=value_display(v)
            if numeric[i] and v is not None: s += txt.rjust(widths[i]) + ' '
            else: s += txt.ljust(widths[i]) + ' '
        lines.append(s)
    return '\n'.join(lines) + '\n'


def write_csv(headers, rows, path):
    out = io.StringIO()
    w = csv.writer(out, lineterminator='\n')
    w.writerow(headers)
    for row in rows:
        w.writerow([('<NULL>' if v is None else v) for v in row])
    data=out.getvalue()
    if path == '-': sys.stdout.write(data)
    else:
        with open(path,'w',newline='') as f: f.write(data)


def write_json(headers, rows, path):
    arr=[]
    for row in rows:
        obj={}
        for h,v in zip(headers,row): obj[h]=v
        arr.append(obj)
    data=json.dumps(arr, indent=4) + '\n'
    if path=='-': sys.stdout.write(data)
    else:
        with open(path,'w') as f: f.write(data)


def command_error(cmd, msg, idx=None, help_line=None):
    eprint(f"  error: {msg}")
    if idx is not None:
        eprint(f" --> command-option:{idx}")
        eprint(" | %-39s" % cmd)
    if help_line:
        eprint(" = help: " + help_line)


def execute_sql(sql: str, records: List[Record]):
    con = setup_db(records)
    cur = con.cursor()
    cur.execute(sql)
    rows = cur.fetchall()
    headers = [d[0] for d in cur.description] if cur.description else []
    data = [tuple(r) for r in rows]
    con.close()
    return headers, data


def expand_script_commands(path: str) -> List[str]:
    if path == '-':
        content = sys.stdin.read().splitlines()
    else:
        if not os.path.exists(path):
            raise FileNotFoundError(path)
        with open(path, errors='replace') as f: content=f.read().splitlines()
    cmds=[]
    for line in content:
        s=line.strip()
        if not s or s.startswith('#'): continue
        cmds.append(s)
    return cmds


def run_commands(commands: List[str], all_records: List[Record], opts: Options):
    filters=[]; offset=0; current_view='log'; last_query=None; printed=False; suppress_default=False
    expanded=[]
    # Expand one level preserving errors as special tokens.
    for c in commands:
        if c.startswith('|'):
            p=c[1:]
            try:
                expanded.extend(expand_script_commands(p))
            except FileNotFoundError:
                command_error(c, f"unknown script -- {p} -- file not found", len(expanded)+1)
                suppress_default=True
        else:
            expanded.append(c)
    for ci,c in enumerate(expanded, start=1):
        if c.startswith(';'):
            sql=c[1:].strip()
            try:
                recs = visible_records(all_records, filters, opts.since, opts.until, offset=0)
                last_query=execute_sql(sql, recs)
                current_view='query'; suppress_default=False
            except Exception as ex:
                eprint("  error: failed to compile SQL statement")
                eprint(f" reason: {ex}")
                eprint(f" --> command-option:{ci}")
                eprint(" | %-39s" % sql)
                suppress_default=True; last_query=None
            continue
        if not c.startswith(':'):
            continue
        body=c[1:].strip(); parts=body.split(None,1); name=parts[0] if parts else ''; arg=parts[1] if len(parts)>1 else ''
        if name in ('filter-in','filter-out'):
            try:
                filters.append(('in' if name=='filter-in' else 'out', re.compile(arg)))
                current_view='log'; last_query=None; suppress_default=False
            except re.error as ex:
                command_error(c, f"invalid regular expression: {ex}", ci)
                suppress_default=True
        elif name in ('clear-filter','clear-filters'):
            filters=[]; current_view='log'; suppress_default=False; last_query=None
        elif name == 'goto':
            try: offset=max(0,int(arg.strip()))
            except Exception: offset=0
            current_view='log'; last_query=None; suppress_default=False
        elif name in ('quit','q'):
            pass
        elif name == 'switch-to-view':
            current_view=arg.strip().lower(); last_query=None; suppress_default=False
        elif name == 'mark-expr':
            expr=arg.strip().lower()
            recs=visible_records(all_records, filters, opts.since, opts.until, offset=0)
            if expr in ('true','1'):
                for r in recs:
                    if r.recognized: r.marked=True
            elif expr in ('false','0'):
                for r in recs: r.marked=False
            else:
                # Support a few pragmatic regex forms; otherwise emit a lnav-like error.
                m=re.search(r'/(.*)/', arg)
                if m:
                    pat=re.compile(m.group(1))
                    for r in recs:
                        if pat.search(r.text): r.marked=True
                else:
                    eprint(f"  error: invalid mark expression: {arg}")
                    eprint(" reason: no such column: " + (arg.split()[0] if arg.split() else ''))
                    eprint(f" --> command-option:{ci}")
                    eprint(" | %-39s" % c)
            current_view='log'; last_query=None; suppress_default=True
        elif name in ('write-to','write-raw-to'):
            path=arg.split()[-1] if arg else ''
            marked=[r for r in visible_records(all_records, filters, opts.since, opts.until, offset=0) if r.marked]
            if not marked:
                command_error(c, "no lines marked to write, use 'm' to mark lines", ci, f":{name} [--anonymize] path" if name=='write-to' else f":{name} [--view] [--anonymize] path")
                suppress_default=True
            else:
                data=''.join(r.display + '\n' for r in marked)
                if path=='-': sys.stdout.write(data); printed=True
                elif path:
                    with open(path,'w') as f: f.write(data)
                suppress_default=True
        elif name == 'write-screen-to':
            path=arg.split()[-1] if arg else ''
            recs=visible_records(all_records, filters, opts.since, opts.until, offset=offset)
            data=''.join(r.display + '\n' for r in recs)
            if path=='-': sys.stdout.write(data); printed=True
            elif path:
                with open(path,'w') as f: f.write(data)
            suppress_default=True
        elif name in ('write-csv-to','write-json-to'):
            path=arg.split()[-1] if arg else ''
            if not last_query:
                command_error(c, "no query result to write, use ';' to execute a query", ci, f":{name} [--anonymize] path")
                suppress_default=True
            else:
                h,rows=last_query
                if name=='write-csv-to': write_csv(h, rows, path)
                else: write_json(h, rows, path)
                printed=True; suppress_default=True; current_view='query'
        else:
            eprint(f"  error: unknown command: {squote(name)}")
            suppress_default=True
    if printed:
        return
    if last_query and not suppress_default:
        h,rows=last_query
        sys.stdout.write(format_table(h, rows))
        return
    if opts.quiet or suppress_default:
        return
    if current_view == 'log':
        for r in visible_records(all_records, filters, opts.since, opts.until, offset=offset):
            sys.stdout.write(r.display + '\n')
    else:
        # text/db/help views produce no headless log dump.
        return


def load_all(opts: Options) -> Tuple[List[Record], int]:
    file_groups=[]; errors=0
    paths = collect_paths(opts.paths, opts.recursive)
    for p in paths:
        if not os.path.exists(p):
            eprint(f"  error: unable to open file: {p}")
            eprint(" reason: No such file or directory")
            errors=1; continue
        if os.path.isdir(p): continue
        try:
            lines=open_text_file(p)
            recs,_=finalize_records(lines, p)
            # Directory mode ignores files that have no recognized log records; explicit file still displays text.
            if len(opts.paths)==1 and os.path.isdir(opts.paths[0]) and not recognized_file(recs):
                continue
            file_groups.append(recs)
        except Exception as ex:
            eprint(f"  error: unable to open file: {p}")
            eprint(f" reason: {ex}")
            errors=1
    # Execute shell commands as captured text.
    for cmd in opts.exec_cmds:
        try:
            cp=subprocess.run(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
            recs,_=finalize_records(cp.stdout.splitlines(True), f"$ {cmd}")
            file_groups.append(recs)
        except Exception as ex:
            recs,_=finalize_records([str(ex)+'\n'], f"$ {cmd}")
            file_groups.append(recs)
    # Stdin is read only when no -N and it is piped. This mirrors the observed behavior.
    if not opts.no_default and not sys.stdin.isatty():
        data=sys.stdin.read().splitlines(True)
        if data:
            recs,_=finalize_records(data, 'stdin', timestamps_for_stdin=opts.stdin_timestamps)
            file_groups.append(recs)
    if not file_groups:
        return [], errors
    return merge_records_by_file(file_groups), errors


def apply_time_range_check(records: List[Record], opts: Options, paths: List[str]) -> bool:
    # Return True if OK.
    vis = visible_records(records, [], opts.since, opts.until, 0)
    if records and not vis and (opts.since or opts.until):
        p = paths[0] if paths else 'stdin'
        eprint(f"  error: unable to open file: {p}")
        eprint(f" reason: file contents are out-of-range of time cutoffs {squote(p)}")
        return False
    return True


def check_config_or_files(opts: Options) -> int:
    if not opts.paths:
        return 0
    code=0
    for p in opts.paths:
        if not os.path.exists(p):
            eprint(f"  error: unable to open file: {p}")
            eprint(" reason: No such file or directory")
            code=1; continue
        try:
            recs,_=finalize_records(open_text_file(p), p)
            if not recognized_file(recs):
                sys.stderr.write(f"error:{p}:no format found for file\n")
                code=1
        except Exception as ex:
            eprint(f"  error: unable to open file: {p}")
            eprint(f" reason: {ex}")
            code=1
    return code


def management_mode(opts: Options) -> int:
    eprint("  error: expecting an operation to perform")
    eprint(" = help: the available operations are:")
    for name,desc in [('apps','manage lnav apps'),('config','perform operations on the lnav configuration'),('format','perform operations on log file formats'),('piper','perform operations on piper storage'),('regex101','create and edit log message regular expressions using regex101.com'),('crash','manage crash logs')]:
        eprint(f"          • {name}: {desc}")
    return 1


def install_mode(opts: Options) -> int:
    if not opts.paths:
        eprint("  error: invalid command-line arguments")
        eprint(" reason: -i requires file")
        return 107
    code=0
    for p in opts.paths:
        try:
            with open(p, errors='replace') as f: json.load(f)
        except Exception as ex:
            eprint(f"  error: unable to open configuration file: {p}")
            # Match common JSON parse wording loosely.
            eprint(" reason: JSON parsing failed -- " + str(ex))
            code=1
    return code


def no_tty_error():
    eprint("  error: unable to display interactive text UI")
    eprint(" reason: stdout is not a TTY")
    eprint(" = help: pass the -n option to run lnav in headless mode or don't redirect stdout")


def interactive(records: List[Record], opts: Options) -> int:
    # Minimal terminal UI: show content and accept q/? for smoke tests.
    try:
        import termios, tty, select
        sys.stdout.write("\033[?1049h\033[H\033[2J")
        lines=[]
        for r in visible_records(records, [], opts.since, opts.until):
            lines.extend(r.display.splitlines())
        if opts.internal_help:
            lines=internal_help_text().splitlines()
        rows = int(os.environ.get('LINES','24') or 24) - 1
        for line in lines[:max(1,rows)]:
            sys.stdout.write(line[:int(os.environ.get('COLUMNS','80') or 80)] + "\r\n")
        sys.stdout.write("-- lnav 0.14.0 -- press q to quit, ? for help --")
        sys.stdout.flush()
        fd=sys.stdin.fileno(); old=termios.tcgetattr(fd); tty.setcbreak(fd)
        try:
            while True:
                r,_,_=select.select([sys.stdin],[],[],0.5)
                if r:
                    ch=sys.stdin.read(1)
                    if ch in ('q','Q','\x03','\x04'): break
                    if ch=='?':
                        sys.stdout.write("\033[H\033[2J" + internal_help_text()[:2000])
                        sys.stdout.flush()
        finally:
            termios.tcsetattr(fd, termios.TCSADRAIN, old)
            sys.stdout.write("\033[?1049l")
            sys.stdout.flush()
    except Exception:
        no_tty_error(); return 1
    return 0


def main(argv):
    opts=parse_args(argv[1:])
    # Help/version override invalid arguments, as observed.
    if opts.help:
        sys.stderr.write(help_text(argv[0])); return 0
    if opts.version:
        sys.stdout.write(VERSION + "\n"); return 0
    if opts.invalid:
        code,msg=opts.invalid; sys.stderr.write(msg); return code
    if opts.management:
        return management_mode(opts)
    if opts.install:
        return install_mode(opts)
    if opts.check:
        return check_config_or_files(opts)
    if opts.update:
        return 0
    if opts.debug_file:
        try:
            with open(opts.debug_file,'a') as f: f.write('')
        except Exception:
            pass
    if opts.internal_help and opts.headless:
        sys.stdout.write(internal_help_text()); return 0
    if opts.warn and opts.headless and not opts.paths:
        eprint("  error: nothing to do")
        eprint(" reason: no files given or default files found")
        eprint(" = help: use the “-N” option to open lnav without loading any files")
        return 1
    records,err=load_all(opts)
    if err and opts.headless:
        return 1
    if not records and not opts.no_default and not opts.exec_cmds and not opts.paths and sys.stdin.isatty():
        eprint("  error: nothing to do")
        eprint(" reason: no files given or default files found")
        eprint(" = help: use the “-N” option to open lnav without loading any files")
        return 1
    if not apply_time_range_check(records, opts, opts.paths):
        return 1
    if opts.headless:
        if opts.commands:
            run_commands(opts.commands, records, opts)
        elif not opts.quiet:
            for r in visible_records(records, [], opts.since, opts.until):
                sys.stdout.write(r.display + '\n')
        return 0 if err==0 else 1
    # Non-headless needs a terminal.
    if not sys.stdout.isatty():
        if err:
            # original prints file errors before the UI error
            pass
        no_tty_error(); return 1
    return interactive(records, opts)

if __name__ == '__main__':
    sys.exit(main(sys.argv))
